import * as THREE from 'three/webgpu';
import {
    NodeMaterial,
    uv,
    texture,
    mix,
    color,
    float,
    vec2,
    vec3,
    mul,
    sin,
    add,
    sub,
    div,
    pow,
    clamp,
    normalize,
    dot
} from 'three/tsl';
import { gsap } from 'gsap';
import primitives from '@/primitives';
import { FontAtlas } from '@/text';

export default function createNode(config, ctx) {
    const group = new THREE.Group();
    group.position.set(0, 0, 0);
    group.rotation.set(0, 0, 0);
    group.scale.set(1, 1, 1);

    // ---------- Backdrop ----------
    const backdropGeom = new THREE.PlaneGeometry(7, 5.5);
    const backdropNodeMat = new NodeMaterial();
    const gradNode = mix(
        color('#0b0b10'),
        color('#13131a'),
        uv().y
    );
    backdropNodeMat.colorNode = gradNode;
    backdropNodeMat.transparent = false;
    const backdropMesh = new THREE.Mesh(backdropGeom, backdropNodeMat);
    backdropMesh.position.set(0, 0, -1.5);
    group.add(backdropMesh);

    // ---------- Font Atlas Helpers ----------
    const atlas = ctx.fontAtlas; // assumed to be instance of FontAtlas
    const atlasTexture = atlas.texture;

    function createGlyphMesh(ch, scaleY, offsetZ = 0) {
        const glyph = atlas.getGlyph(ch);
        const glyphHeight = scaleY;
        const glyphWidth = glyphHeight * glyph.aspect; // aspect = width/height

        const geom = new THREE.PlaneGeometry(glyphWidth, glyphHeight);
        const mat = new NodeMaterial();
        mat.transparent = true;
        mat.depthWrite = false;
        // use the shared atlas texture
        const texNode = texture(atlasTexture);
        mat.mapNode = texNode;

        // UV transform to isolate glyph region
        const uvNode = uv()
            .multiply(vec2(glyph.uSize, glyph.vSize))
            .add(vec2(glyph.u0, glyph.v0));
        mat.uvNode = uvNode;

        // default color (white, modulated by material color later)
        mat.colorNode = vec3(1, 1, 1);
        // start invisible – kinetic primitive will animate opacity
        mat.opacityNode = float(0);

        const mesh = new THREE.Mesh(geom, mat);
        mesh.position.set(0, 0, offsetZ);
        mesh.userData.char = ch;
        return mesh;
    }

    // ---------- Hero Headline ----------
    const heroString = "TIME, MACHINED.";
    const heroEmHeight = 0.62; // scene units
    const heroColor = new THREE.Color('#16161d');
    const heroGroup = new THREE.Group();
    heroGroup.position.set(0, 0.4, 0);

    const wordOffsets = [0.12, 0.0, -0.12]; // front‑to‑back per word
    const words = heroString.split(' ');
    let cursorX = 0;
    const glyphMeshes = [];

    words.forEach((word, wi) => {
        const zOffset = wordOffsets[wi] ?? 0;
        for (let i = 0; i < word.length; i++) {
            const ch = word[i];
            const glyphMesh = createGlyphMesh(ch, heroEmHeight, zOffset);
            glyphMesh.position.x = cursorX;
            const adv = atlas.getAdvance(ch) * heroEmHeight;
            cursorX += adv;
            glyphMeshes.push(glyphMesh);
            heroGroup.add(glyphMesh);
        }
        // add space advance after each word except last
        if (wi < words.length - 1) {
            const spaceAdv = atlas.getAdvance(' ') * heroEmHeight;
            cursorX += spaceAdv;
        }
    });

    // centre the whole line
    heroGroup.position.x = -cursorX / 2;
    group.add(heroGroup);

    // kinetic‑text primitive (entrance animation)
    if (primitives['kinetic-text']) {
        primitives['kinetic-text'](heroGroup, { staggerMs: 60, riseUnits: 0.35 });
    }

    // ---------- Accent Underline ----------
    const underlineGeom = new THREE.PlaneGeometry(2.6, 0.045);
    const underlineMat = new NodeMaterial();
    underlineMat.transparent = true;
    underlineMat.colorNode = color('#ff2a38');
    underlineMat.emissiveNode = mul(color('#ff2a38'), float(1.2));
    const underlineMesh = new THREE.Mesh(underlineGeom, underlineMat);
    // anchored left under the hero line
    underlineMesh.position.set(-cursorX / 2, -0.05, 0);
    underlineMesh.scale.set(0, 1, 1); // start collapsed
    group.add(underlineMesh);

    // timeline for underline reveal after last glyph settles
    const totalGlyphTime = glyphMeshes.length * 0.06 + 0.7; // stagger + rise duration
    const underlineTL = gsap.timeline();
    underlineTL.delay(totalGlyphTime + 0.12);
    underlineTL.to(underlineMesh.scale, { x: 1, duration: 0.5, ease: "power2.out" });

    // ---------- Subhead ----------
    const subheadString = "Every calibre begins as a solid billet.";
    const subEmHeight = 0.2;
    const subGroup = new THREE.Group();
    subGroup.position.set(0, -0.65, 0);

    let subCursor = 0;
    const subGlyphs = [];

    for (let i = 0; i < subheadString.length; i++) {
        const ch = subheadString[i];
        const g = createGlyphMesh(ch, subEmHeight, 0);
        g.position.x = subCursor;
        const adv = atlas.getAdvance(ch) * subEmHeight;
        subCursor += adv;
        subGlyphs.push(g);
        subGroup.add(g);
    }
    subGroup.position.x = -subCursor / 2;
    group.add(subGroup);

    // subhead fade‑up animation
    gsap.from(subGroup.position, {
        y: subGroup.position.y + 0.2,
        duration: 0.5,
        ease: "power2.out",
        delay: totalGlyphTime + 0.2
    });
    gsap.from(
        subGlyphs.map(m => m.material),
        {
            opacity: 0,
            duration: 0.5,
            ease: "power2.out",
            delay: totalGlyphTime + 0.2,
            stagger: 0.03
        }
    );

    // ---------- Caption Kicker ----------
    const captionString = "NOVA ATELIER / CALIBRE PROGRAM";
    const capEmHeight = 0.09;
    const capGroup = new THREE.Group();
    capGroup.position.set(0, 1.15, 0);

    let capCursor = 0;
    for (let i = 0; i < captionString.length; i++) {
        const ch = captionString[i];
        const g = createGlyphMesh(ch, capEmHeight, 0);
        g.position.x = capCursor;
        const adv = atlas.getAdvance(ch) * capEmHeight;
        capCursor += adv;
        capGroup.add(g);
    }
    capGroup.position.x = -capCursor / 2;
    group.add(capGroup);

    // ---------- Apply Additional Cinematic Primitives ----------
    if (Array.isArray(config.cinematicPrimitives)) {
        config.cinematicPrimitives.forEach(p => {
            const fn = ctx.primitives[p.name];
            if (fn) fn(group, p.params);
        });
    }

    // ---------- Cleanup ----------
    group.userData.handlers = {};

    group.userData.cleanup = () => {
        // dispose meshes
        group.traverse(obj => {
            if (obj.isMesh) {
                if (obj.geometry) obj.geometry.dispose();
                if (obj.material) {
                    if (Array.isArray(obj.material)) {
                        obj.material.forEach(m => m.dispose());
                    } else {
                        obj.material.dispose();
                    }
                }
            }
        });
        // kill GSAP timelines
        gsap.killTweensOf(underlineMesh.scale);
        gsap.killTweensOf(subGroup.position);
        underlineTL.kill();
    };

    return group;
}
